import { get, push, ref, remove, runTransaction, set, update } from 'firebase/database';

import {
  PUBLIC_COMMENTS_ROOT_PATH,
  database,
  removeCardAndSearchId,
  reportSearchIdIndexFailure,
  syncUserSearchKeyIndex,
  syncMatchingCardIndex,
} from 'components/config';
import { buildOverlayFromDraft, getOverlaysForCard, purgeCardOverlays } from './multiAccountEdits';
import { getProfileMutationOwnerPath } from './profileDraftIndexing';
import { buildProfileNodePatch } from './profileNodeWriter';
import {
  SEARCH_ID_INDEXED_FIELDS,
  appendSearchIdEntryId,
  buildSearchIdClaimKey,
  buildSearchIdEntryPath,
  describeSearchIdRecord,
  readSearchIdEntryIds,
  removeSearchIdEntryId,
} from './searchKeyUtils';

export const PROFILE_MUTATIONS_ROOT = 'multiData/profileMutations';
export const PROFILE_IDENTITY_CLAIMS_ROOT = 'multiData/profileIdentityClaims';
export const PROFILE_MUTATION_HISTORY_ROOT = 'multiData/profileMutationHistory';

export const getProfileMutationPath = (creatorUid, cardId) => (
  `${PROFILE_MUTATIONS_ROOT}/${creatorUid}${cardId ? `/${cardId}` : ''}`
);

export const getProfileIdentityClaimPath = claimKey => (
  `${PROFILE_IDENTITY_CLAIMS_ROOT}/${claimKey}`
);

export const getProfileMutationHistoryPath = cardId => (
  `${PROFILE_MUTATION_HISTORY_ROOT}/${cardId}`
);

const cleanObject = value => Object.entries(value || {}).reduce((result, [key, item]) => {
  if (key.startsWith('__') || item === undefined) return result;
  result[key] = item;
  return result;
}, {});

const withProfileSaveStage = async (profileSaveStage, operation) => {
  try {
    return await operation();
  } catch (error) {
    error.profileSaveStage = profileSaveStage;
    throw error;
  }
};

export const buildProfileRevisionHistory = ({ cardId, actorUid, previousData, nextData, at, revision }) => (
  previousData == null ? [] : Object.entries(buildOverlayFromDraft(previousData, nextData || {}))
    .map(([fieldName, change]) => ({
      cardId,
      actorUid,
      editorUserId: actorUid,
      action: 'edit',
      fieldName,
      change,
      at,
      revision,
    }))
);

export const getEffectiveProfile = ({ baseProfile, mutation } = {}) => {
  if (mutation?.status === 'accepted' || mutation?.status === 'archived') return baseProfile || null;
  if (mutation?.operation === 'create' && !baseProfile) {
    return { ...cleanObject(mutation.data), userId: mutation.cardId };
  }
  if (mutation?.operation === 'update' && baseProfile) {
    return { ...baseProfile, ...cleanObject(mutation.data) };
  }
  return baseProfile || null;
};

export const reserveProfileCardId = () => push(ref(database, PROFILE_MUTATIONS_ROOT)).key;

/**
 * Значення чернетки, які мають опинитись в індексі, — разом із полем.
 *
 * Поле тепер частина запису (`searchId/{значення}/{поле}`), а не частина
 * ключа, тож воно носиться поруч зі значенням: за ним і пишеться id, і
 * звіряється зайнятість. Заявка на унікальність лишається в старій формі
 * `{поле}_{значення}` — див. `buildSearchIdClaimKey`.
 */
const getSearchIdRecords = (data, { contactsOnly = false } = {}) => Object.entries(cleanObject(data))
  .filter(([field]) => SEARCH_ID_INDEXED_FIELDS.has(field) && (!contactsOnly || (field !== 'name' && field !== 'surname')))
  .flatMap(([field, rawValue]) => (Array.isArray(rawValue) ? rawValue : [rawValue])
    .map(value => describeSearchIdRecord({ [field]: value }))
    .filter(Boolean))
  .filter((record, index, records) => records.findIndex(item => item.path === record.path) === index);

const hashKey = value => {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
};

const keyByteLength = key => new TextEncoder().encode(key).length;

// RTDB limits a child key to 768 UTF-8 bytes. Claims need only be stable and
// collision-resistant within their field, so bound pathological form values.
const getIdentityClaimKey = ({ field, valueKey }) => {
  const claimKey = buildSearchIdClaimKey(field, valueKey);
  return keyByteLength(claimKey) <= 700 ? claimKey : `${field}_hash_${hashKey(claimKey)}`;
};

/**
 * Id із `searchId` — ще не доказ, що картка існує.
 *
 * Індекс знімається не завжди: попередня версія поля лишається в ньому
 * навмисно, а видалена картка могла лишити ключ, якщо видалення впало на
 * півдорозі. Такий «сирота» блокував контакт назавжди — значення ставало
 * зайнятим карткою, якої немає ніде. Дублем рахується лише id, за яким
 * стоїть картка стрічки або чернетка (`profileMutationOwners`); чернетки без
 * цієї пари стереже її власна заявка на унікальність нижче. Відмова в
 * читанні — не «картки немає»: такий id лишається конфліктом.
 */
const keepExistingCardIds = async cardIds => {
  const checks = await Promise.all(cardIds.map(async id => {
    try {
      const [card, owner] = await Promise.all([
        get(ref(database, `matchingCards/${id}`)),
        get(ref(database, getProfileMutationOwnerPath(id))),
      ]);
      return card?.exists?.() || owner?.exists?.();
    } catch {
      return true;
    }
  }));
  return cardIds.filter((_, index) => checks[index]);
};

const claimProfileIdentities = async ({ cardId, data }) => {
  const searchRecords = getSearchIdRecords(data, { contactsOnly: true });
  const keys = searchRecords.map(getIdentityClaimKey);
  // Зайнятість питається саме того поля, у якому лежить значення. Раніше ключ
  // ніс поле в собі, тож інакше й не виходило; тепер під одним значенням
  // можуть стояти різні поля — і чужий нікнейм, що збігся з номером, не має
  // означати «такий телефон уже є».
  const checkedRecords = searchRecords.filter(record => keyByteLength(record.valueKey) <= 768);
  const indexedValues = await Promise.all(checkedRecords
    .map(record => get(ref(database, buildSearchIdEntryPath(record.valueKey, record.field)))));
  const candidateConflicts = checkedRecords
    .map((record, index) => ({
      field: record.field,
      cardIds: readSearchIdEntryIds(indexedValues[index].val()).filter(id => id !== cardId),
    }))
    .filter(conflict => conflict.cardIds.length);
  const canonicalConflicts = (await Promise.all(candidateConflicts.map(async conflict => ({
    ...conflict,
    cardIds: await keepExistingCardIds(conflict.cardIds),
  })))).filter(conflict => conflict.cardIds.length);
  // Дубль контакту — не відмова, а попередження. Значення зберігається, а
  // поле й картки, які його вже мають, повертаються (`conflicts`) — екран
  // каже про них людині, а розсуджує дублі адмін окремо (порівняння
  // дублікатів на `AddNewProfile`). Поки збіг кидав `DUPLICATE_PROFILE`,
  // одне дописане значення (нік телеграму від адміна) зупиняло збереження
  // чернетки цілком, і кожен наступний blur будь-якого поля давав ту саму
  // відмову — тобто губилась і решта правок.
  const conflicts = [...canonicalConflicts];
  const noteConflict = (field, ids) => {
    const existing = conflicts.find(conflict => conflict.field === field);
    if (existing) {
      existing.cardIds = [...new Set([...existing.cardIds, ...ids])];
    } else {
      conflicts.push({ field, cardIds: ids });
    }
  };
  const ownedKeys = [];
  const acquiredKeys = [];
  try {
    for (const [index, key] of keys.entries()) {
      const claimRef = ref(database, getProfileIdentityClaimPath(key));
      const existingSnapshot = await get(claimRef);
      const alreadyOwned = existingSnapshot.val() === cardId;
      let claimedBy = null;
      const result = await runTransaction(claimRef, current => {
        if (current != null && current !== cardId) {
          claimedBy = typeof current === 'string' ? current : '';
          return undefined;
        }
        return cardId;
      }, { applyLocally: false });
      if (!result.committed) {
        if (claimedBy == null) throw new Error('REVISION_CONFLICT');
        // Заявку тримає інша картка — її не перебиваємо: вона лишається за
        // тим, хто завів контакт першим, а ця картка просто зберігає значення.
        noteConflict(searchRecords[index].field, claimedBy ? [claimedBy] : []);
        continue;
      }
      ownedKeys.push(key);
      if (!alreadyOwned) acquiredKeys.push(key);
    }
  } catch (error) {
    await releaseProfileIdentities(cardId, acquiredKeys).catch(() => {});
    throw error;
  }
  return { keys: ownedKeys, acquiredKeys, conflicts };
};

const releaseProfileIdentities = (cardId, keys) => Promise.all((keys || []).map(key => runTransaction(
  ref(database, getProfileIdentityClaimPath(key)),
  current => (current === cardId ? null : current),
  { applyLocally: false },
)));

/**
 * Запис, який нічого не міняє, — це не дешевий запис, а відмова.
 *
 * Правила дають авторові чернетки рівно право **завести** запис у `searchId`
 * (`newData.isString() && !data.exists() && ...` у `database.rules.json`), а не
 * переписати вже заведений. Тож транзакція, яка повертала те саме значення, що
 * вже лежить у базі, відлітала з `PERMISSION_DENIED` — на **кожному** blur, по
 * ключу на кожне індексоване значення чернетки. Памʼять таба від цього не
 * рятувала: вона ставиться після вдалого запису, а цей не вдавався ніколи.
 *
 * Коштувало це не лише круга до бази на дотик. Відмову видно людині: адмінові
 * тостом, решті — `console.warn`, обидва зі словами «ключ чернетки не записано
 * в searchId». Тобто застосунок на кожному дотику повідомляв, що набраний
 * телефон не потрапив в індекс, хоч той лежав там з першого ж збереження, —
 * і виглядало це рівно як «номер із чернетки не індексується».
 *
 * `undefined` перериває транзакцію без запису, тож ключ, у якому цієї картки
 * ще немає, пишеться як писався: додати id в одиночний рядок чи в масив —
 * зміна, і правила її пропускають.
 */
const sameSearchIdEntry = (current, next) => {
  if (Array.isArray(current) && Array.isArray(next)) {
    return current.length === next.length && current.every((id, index) => id === next[index]);
  }
  return current === next;
};

const addCardIdToSearchIdEntry = cardId => current => {
  const next = appendSearchIdEntryId(current, cardId);
  return sameSearchIdEntry(current, next) ? undefined : next;
};

const syncProfileSearchIdIndex = (cardId, profile) => Promise.all(
  getSearchIdRecords(profile)
    .filter(record => keyByteLength(record.valueKey) <= 768)
    .map(record => runTransaction(
      ref(database, buildSearchIdEntryPath(record.valueKey, record.field)),
      addCardIdToSearchIdEntry(cardId),
      { applyLocally: false },
    )),
);

/**
 * Те саме, що `syncProfileSearchIdIndex`, але для чернетки — і без права впасти.
 *
 * Публікація на відмову індексації відкочує перехід (`acceptCreateProfileMutation`):
 * там ключ уже частина того, що обіцяно показати. Автозбереження чернетки —
 * навпаки: воно спрацьовує на кожному blur, і загублена анкета коштує людині
 * більше, ніж ненаписаний ключ. Тож кожен ключ падає окремо й називає себе —
 * і в консолі, і тостом адмінові, бо правила під цей запис викочуються руками.
 *
 * Памʼять таба тут не оптимізація, а умова. Збереження йде на **кожен** blur, а
 * значень у чернетці десяток: без неї заповнення однієї картки коштувало б
 * сотень транзакцій по тих самих ключах. Це та сама памʼять, що й
 * `confirmedSearchIdEntries` в `config.js`, і ставиться вона так само — **після**
 * того, як круг до бази скінчився без відмови, тож ключ, що не записався
 * (нерозгорнуті правила), наступне збереження пробує знову. Перервана
 * транзакція (`addCardIdToSearchIdEntry`) теж лишає позначку: id у записі вже
 * стоїть, і питати про нього ще раз нема чого.
 */
const confirmedDraftSearchIdEntries = new Set();

const draftSearchIdRecords = profile => getSearchIdRecords(profile)
  .filter(record => keyByteLength(record.valueKey) <= 768);

const indexDraftSearchIdEntries = (cardId, profile) => Promise.all(
  draftSearchIdRecords(profile)
    .filter(record => !confirmedDraftSearchIdEntries.has(`${record.path}|${cardId}`))
    .map(record => runTransaction(
      ref(database, record.path),
      addCardIdToSearchIdEntry(cardId),
      { applyLocally: false },
    ).then(() => {
      confirmedDraftSearchIdEntries.add(`${record.path}|${cardId}`);
    }).catch(error => {
      console.warn('[profileMutations] ключ чернетки не записано в searchId', {
        cardId,
        path: record.path,
        error,
      });
      reportSearchIdIndexFailure({
        searchIdKey: `${record.valueKey}/${record.field}`,
        action: 'add',
        error,
      });
    })),
);

// Remove keys which disappeared from the draft as well as adding new ones.
// Without this half of the sync, clearing a draft hid it in the UI but left
// its old contacts discoverable and (through identity claims) unavailable to
// a replacement card.
const removeStaleDraftSearchIdEntries = (cardId, previousProfile, nextProfile) => {
  const nextPaths = new Set(draftSearchIdRecords(nextProfile).map(record => record.path));
  return Promise.all(draftSearchIdRecords(previousProfile)
    .filter(record => !nextPaths.has(record.path))
    .map(record => runTransaction(
      ref(database, record.path),
      current => removeSearchIdEntryId(current, cardId),
      { applyLocally: false },
    ).then(() => {
      confirmedDraftSearchIdEntries.delete(`${record.path}|${cardId}`);
    }).catch(error => {
      console.warn('[profileMutations] старий ключ чернетки не знято з searchId', {
        cardId,
        path: record.path,
        error,
      });
      reportSearchIdIndexFailure({
        searchIdKey: `${record.valueKey}/${record.field}`,
        action: 'remove',
        error,
      });
    })));
};

/**
 * Записати «цю картку завів я» — щоб знайдену чернетку міг прочитати не лише
 * її автор і не лише службовий читач.
 *
 * Пишеться **раз на таб на картку**: значення не міняється ніколи (автор
 * чернетки один), а збереження йде на кожен blur. Памʼять та сама за змістом,
 * що й у `indexDraftSearchIdEntries`, і ставиться так само — після круга, що
 * скінчився без відмови.
 *
 * Відмова збереження не валить з тієї самої причини: без цього запису
 * чернетку й далі знайде автор та адмін, тобто рівно те, що було, — а
 * загублена анкета коштує людині більше. Але мовчати не можна: правила під
 * цей вузол викочуються руками (`npx firebase deploy --only database`), і
 * поки їх немає, кожна нова чернетка лишається невидимою звичайному читачеві.
 */
const confirmedDraftOwners = new Set();

const indexDraftOwner = async (cardId, creatorUid) => {
  const path = getProfileMutationOwnerPath(cardId);
  if (!path || !creatorUid || confirmedDraftOwners.has(`${path}|${creatorUid}`)) return;
  try {
    await set(ref(database, path), creatorUid);
    confirmedDraftOwners.add(`${path}|${creatorUid}`);
  } catch (error) {
    console.warn('[profileMutations] автора чернетки не записано', { cardId, path, error });
    reportSearchIdIndexFailure({ searchIdKey: path, action: 'add', error });
  }
};

export const saveCreateProfileMutation = async ({
  cardId,
  creatorUid,
  actorUid,
  data,
  expectedRevision,
  skipRevisionHistory = false,
}) => {
  if (!cardId || !creatorUid || !actorUid) throw new Error('cardId, creatorUid and actorUid are required');
  let identityKeys;
  let acquiredIdentityKeys;
  let duplicateConflicts;
  try {
    ({
      keys: identityKeys,
      acquiredKeys: acquiredIdentityKeys,
      conflicts: duplicateConflicts,
    } = await claimProfileIdentities({ cardId, data }));
  } catch (error) {
    error.profileSaveStage = 'identity-claim';
    throw error;
  }
  let conflict = '';
  let previousIdentityKeys = [];
  let previousData = {};
  let revisionHistory = [];
  let result;
  try {
    result = await runTransaction(ref(database, getProfileMutationPath(creatorUid, cardId)), current => {
      previousIdentityKeys = current?.identityKeys || [];
      previousData = current?.data || {};
      if (current && current.createdBy !== creatorUid) {
        conflict = 'Profile mutation belongs to another user';
        return undefined;
      }
      // A previous client/version may have failed after the temporary
      // publishing transition. Treat the next explicit autosave as recovery
      // instead of permanently trapping the draft in REVISION_CONFLICT.
      if (current && current.status !== 'pendingReview' && current.status !== 'private' && current.status !== 'publishing') {
        conflict = 'REVISION_CONFLICT';
        return undefined;
      }
      if (current && expectedRevision != null && Number(current.revision) !== Number(expectedRevision)) {
        conflict = 'REVISION_CONFLICT';
        return undefined;
      }
      const now = Date.now();
      const revision = Number(current?.revision || 0) + 1;
      // Use the same normalization/diff representation as editor overlays so
      // both audit streams can be rendered by the same admin UI.
      revisionHistory = skipRevisionHistory ? [] : buildProfileRevisionHistory({
        cardId,
        actorUid,
        previousData: current?.data,
        nextData: data,
        at: now,
        revision,
      });
      return {
        cardId,
        operation: 'create',
        data: { ...cleanObject(data), userId: cardId },
        createdBy: creatorUid,
        createdAt: current?.createdAt || now,
        updatedAt: now,
        revision,
        status: 'pendingReview',
        ...(current?.status === 'publishing' ? { acceptedAt: null } : {}),
        identityKeys,
      };
    }, { applyLocally: false });
  } catch (error) {
    await releaseProfileIdentities(cardId, acquiredIdentityKeys).catch(() => {});
    error.profileSaveStage = 'profile-mutation';
    throw error;
  }
  if (!result.committed) {
    // Only keys absent from the durable draft were acquired by this failed save.
    const existing = result.snapshot.val();
    const newlyClaimed = identityKeys.filter(key => !(existing?.identityKeys || []).includes(key));
    await releaseProfileIdentities(cardId, newlyClaimed);
    throw new Error(conflict || 'REVISION_CONFLICT');
  }
  const mutation = result.snapshot.val();
  if (revisionHistory.length) {
    const historyRef = ref(database, getProfileMutationHistoryPath(cardId));
    const historyUpdates = revisionHistory.reduce((entries, entry) => {
      const key = push(historyRef).key;
      if (key) entries[key] = entry;
      return entries;
    }, {});
    if (Object.keys(historyUpdates).length) await update(historyRef, historyUpdates);
  }
  // Чернетка потрапляє в `searchId` тут, а не аж на публікації.
  //
  // Це єдине місце, де чернетку взагалі видно пошуку: картки стрічки й вузлів
  // анкети в неї немає, тож зведення з пʼятьох вузлів її не бачить. Поки запис
  // стояв самим лише в `acceptCreateProfileMutation`, заведений номер до
  // індексу не доїжджав узагалі — на нього ставили тільки заявку на
  // унікальність (`profileIdentityClaims`), а вона стереже дубль і пошуку не
  // відповідає. Знаходилась така чернетка рівно в одному випадку: коли адмін
  // руками перебудовував індекс (`loadProfileDraftsForIndexing`), тобто дні по
  // тому, як її завели, — а до того автор бачив свою картку (її доливає
  // `personalCreateProfiles`), і більше не бачив її ніхто.
  //
  // Відмова індексації збереження не валить — рівно з тієї ж причини, з якої
  // її ковтає `updateSearchId`: ключ це прискорення пошуку, а не частина
  // анкети, і `PERMISSION_DENIED` на ньому не має коштувати людині набраного.
  // Але й мовчати про неї не можна: правила бази під цей запис викочуються
  // руками (`npx firebase deploy --only database`), і поки їх немає, кожна
  // нова чернетка тихо лишалась би поза пошуком.
  await Promise.all([
    removeStaleDraftSearchIdEntries(cardId, previousData, mutation.data),
    indexDraftSearchIdEntries(cardId, mutation.data),
  ]);
  // Той самий крок, але для «хто автор»: без нього знайдена чернетка
  // відкривається рівно авторові й службовому читачеві (див.
  // `PROFILE_MUTATION_OWNERS_NODE`).
  await indexDraftOwner(cardId, mutation.createdBy || creatorUid);
  // Cleanup is idempotent bookkeeping after the revision is already committed.
  await releaseProfileIdentities(cardId, previousIdentityKeys.filter(key => !identityKeys.includes(key))).catch(error => {
    console.warn('[profileMutations] старі заявки на унікальність не знято', { cardId, error });
  });
  // Збіги з іншими картками їдуть поруч із записом, а не в ньому: це
  // попередження цьому збереженню, а не стан чернетки, тож неперелічуване
  // поле не потрапляє ні в кеш, ні в копії обʼєкта.
  if (duplicateConflicts?.length && mutation && typeof mutation === 'object') {
    Object.defineProperty(mutation, 'duplicateConflicts', { value: duplicateConflicts, enumerable: false });
  }
  return mutation;
};

// Admin-only reader. Its shape intentionally matches overlay history.
export const loadProfileMutationHistory = async cardId => {
  if (!cardId) return [];
  const snapshot = await get(ref(database, getProfileMutationHistoryPath(cardId)));
  if (!snapshot.exists()) return [];
  return Object.entries(snapshot.val() || {})
    .filter(([, entry]) => entry && typeof entry === 'object' && !Array.isArray(entry))
    .map(([entryId, entry]) => ({
      entryId: `revision-${entryId}`,
      backendEntryId: entryId,
      historySource: 'revision',
      ...entry,
    }))
    .sort((a, b) => Number(b.at || 0) - Number(a.at || 0));
};

export const removeProfileMutationHistoryEntry = async ({ cardId, entryId }) => {
  if (!cardId || !entryId) return;
  await remove(ref(database, `${getProfileMutationHistoryPath(cardId)}/${entryId}`));
};

const profileHistoryChangeValues = change => {
  if (!change || typeof change !== 'object' || Array.isArray(change)) return [];
  const values = [];
  if ('from' in change || 'to' in change) values.push(change.from, change.to);
  ['added', 'add', 'removed'].forEach(key => {
    const items = Array.isArray(change[key]) ? change[key] : [change[key]];
    values.push(...items);
  });
  return [...new Set(values.map(value => String(value ?? '').trim()).filter(Boolean))];
};

// A value can occur in several saved revisions (and in the overlay journal).
// Timeline save/delete actions remove every matching revision rather than only
// the particular row that happened to be clicked.
export const purgeProfileMutationHistoryValue = async ({ cardId, fieldName, values = [] }) => {
  if (!cardId || !fieldName) return 0;
  const matchedValues = new Set(values.map(value => String(value ?? '').trim()).filter(Boolean));
  if (!matchedValues.size) return 0;

  const historyRef = ref(database, getProfileMutationHistoryPath(cardId));
  const snapshot = await get(historyRef);
  if (!snapshot.exists()) return 0;
  const updates = Object.entries(snapshot.val() || {}).reduce((result, [entryId, entry]) => {
    if (!entry || entry.fieldName !== fieldName) return result;
    if (!profileHistoryChangeValues(entry.change).some(value => matchedValues.has(value))) return result;
    result[entryId] = null;
    return result;
  }, {});
  if (Object.keys(updates).length) await update(historyRef, updates);
  return Object.keys(updates).length;
};

export const loadProfileMutation = async (creatorUid, cardId) => {
  if (!creatorUid || !cardId) return null;
  const snapshot = await get(ref(database, getProfileMutationPath(creatorUid, cardId)));
  return snapshot.exists() ? snapshot.val() : null;
};

/**
 * Картки, які завів цей користувач.
 *
 * Прийняту адміном картку (`accepted`) за замовчуванням не віддаємо: у стрічці
 * вона вже стоїть звичайною анкетою, і долити її туди вдруге означало б
 * показати дубль. Але на екрані «Створені мною» питання інше — «що я тут
 * завів», — і відповідь без опублікованих карток була б неповною: людина
 * заводила картку, її прийняли, і зі списку вона зникала без сліду.
 */
export const loadOwnProfileMutations = async (creatorUid, { includeAccepted = false } = {}) => {
  if (!creatorUid) return [];
  const snapshot = await get(ref(database, getProfileMutationPath(creatorUid)));
  if (!snapshot.exists()) return [];
  return Object.values(snapshot.val() || {}).filter(item => (
    item && item.createdBy === creatorUid && (includeAccepted || item.status !== 'accepted')
  ));
};

// Drafts somebody else created that this user may open and edit. Only cards
// still waiting for review are shared: a draft an admin sent back to
// `private` belongs to its author again, and an accepted one is a normal
// card. Editing one of these never writes to the author's node - the edits
// land in the editor's own overlay (multiData/edits/{cardId}/{editorUid}).
export const loadSharedProfileMutations = async viewerUid => {
  const snapshot = await get(ref(database, PROFILE_MUTATIONS_ROOT));
  if (!snapshot.exists()) return [];
  return Object.values(snapshot.val() || {}).flatMap(creatorMutations => (
    Object.values(creatorMutations || {})
  )).filter(item => (
    item?.operation === 'create'
    && item.status === 'pendingReview'
    && item.createdBy
    && item.createdBy !== viewerUid
  ));
};

export const loadAllCreateProfileMutations = async () => {
  const snapshot = await get(ref(database, PROFILE_MUTATIONS_ROOT));
  if (!snapshot.exists()) return [];
  return Object.values(snapshot.val() || {}).flatMap(creatorMutations => (
    Object.values(creatorMutations || {})
  )).filter(item => (
    item?.operation === 'create' && item.status !== 'accepted' && item.status !== 'accepting'
  ));
};

export const acceptCreateProfileMutation = async ({ cardId, creatorUid, expectedRevision, finalData }) => {
  if (!cardId || !creatorUid) throw new Error('cardId and creatorUid are required');
  const acceptedAt = Date.now();
  let conflict = 'Profile mutation not found';
  let acceptedProfile = null;
  const mutationPath = getProfileMutationPath(creatorUid, cardId);
  const pendingMutation = await withProfileSaveStage('mutation-transition', async () => {
    const mutationSnapshot = await get(ref(database, mutationPath));
    const currentMutation = mutationSnapshot.val();
    if (!currentMutation) throw new Error(conflict);
    if (currentMutation.operation !== 'create') throw new Error('Profile mutation is not a create mutation');
    return currentMutation;
  });
  const candidateProfile = { ...cleanObject(finalData || pendingMutation.data), userId: cardId };
  const { keys: identityKeys, acquiredKeys: acquiredIdentityKeys } = await withProfileSaveStage(
    'identity-claim',
    () => claimProfileIdentities({ cardId, data: candidateProfile }),
  );
  const previousIdentityKeys = pendingMutation.identityKeys || [];
  const restorePendingMutation = () => runTransaction(ref(database, mutationPath), current => (
    current?.status === 'publishing' && current?.acceptedAt === acceptedAt
      ? { ...current, status: pendingMutation.status, acceptedAt: null }
      : current
  ), { applyLocally: false });
  let result;
  try {
    result = await runTransaction(ref(database, mutationPath), mutation => {
      // The Web SDK can invoke an updater with null before its local cache has
      // the value just read from the server. Returning null (rather than
      // aborting or restoring pendingMutation) lets the transaction compare
      // that state with the server: an existing value causes a retry, while a
      // concurrently deleted value remains deleted.
      if (!mutation) {
        conflict = 'Profile mutation not found';
        return null;
      }
      if (mutation.operation !== 'create') {
        conflict = 'Profile mutation is not a create mutation';
        return undefined;
      }
      if (mutation.status !== 'pendingReview' && mutation.status !== 'private' && mutation.status !== 'publishing') {
        conflict = 'Profile mutation is not publishable';
        return undefined;
      }
      if (Number(mutation.revision) !== Number(expectedRevision)) {
        conflict = 'REVISION_CONFLICT';
        return undefined;
      }
      acceptedProfile = candidateProfile;
      return { ...mutation, data: acceptedProfile, identityKeys, status: 'publishing', acceptedAt };
    }, { applyLocally: false });
  } catch (error) {
    await releaseProfileIdentities(cardId, acquiredIdentityKeys).catch(() => {});
    error.profileSaveStage = 'mutation-transition';
    throw error;
  }
  if (!result.committed || !result.snapshot.val()) {
    await releaseProfileIdentities(cardId, identityKeys.filter(key => !previousIdentityKeys.includes(key)));
    const error = new Error(conflict);
    error.profileSaveStage = 'mutation-transition';
    throw error;
  }
  const mutation = result.snapshot.val();
  // Finish all fallible index work before the single publication update. A
  // publishing record is deliberately retryable after an interrupted attempt.
  try {
    await withProfileSaveStage(
      'search-id-index',
      () => syncProfileSearchIdIndex(cardId, acceptedProfile),
    );
    await withProfileSaveStage(
      'search-key-index',
      () => syncUserSearchKeyIndex(cardId, {}, acceptedProfile),
    );
  } catch (error) {
    await restorePendingMutation().catch(() => {});
    throw error;
  }
  const pendingOverlays = await getOverlaysForCard(cardId).catch(error => {
    console.warn('[profileMutations] pending overlays unavailable', error);
    return {};
  });
  // Once the canonical card is published, unresolved proposals are a private
  // admin review queue. Keep their fields intact and mark only the existing
  // editor nodes; non-admin profile screens ignore this marker.
  const pendingOverlayVisibility = Object.keys(pendingOverlays).reduce((updates, editorUserId) => {
    updates[`multiData/edits/${cardId}/${editorUserId}/adminOnly`] = true;
    return updates;
  }, {});

  // Анкета лягає у власні вузли, а не в legacy `/users`. `/users` — вузол
  // акаунтів, і його дзеркалять для мобільного застосунку; у картки, яку завела
  // адміністраторка, акаунта немає, тож у `/users` вона лише вдавала б його.
  // Веб же з legacy не читає взагалі: анкету збирає `readProfileFromNodes`, і
  // до цієї правки опублікована чернетка не мала в нових вузлах жодного поля.
  //
  // Keep the critical atomic publication deliberately small. Optional review
  // bookkeeping has stricter/legacy rules and must never prevent the profile
  // nodes from being published together with its mutation.
  const publishedNodes = buildProfileNodePatch(cardId, acceptedProfile);
  // Анкета мусить існувати хоча б в одному вузлі: правило картки стрічки питає
  // саме про це. Чернетка, у якій заповнене лише те, що живе в самій картці
  // (імʼя, місто, дата народження), власних полів у вузлах не має — тоді вузол
  // відкриває дата публікації, у тому ж вигляді, у якому її кладе `makeNewUser`.
  if (!Object.keys(publishedNodes).length) {
    publishedNodes[`profileTechnical/${cardId}/createdAt`] = new Date(acceptedAt)
      .toISOString()
      .split('T')[0];
  }
  try {
    await withProfileSaveStage('publication-update', () => update(ref(database), {
      ...publishedNodes,
      [mutationPath]: { ...mutation, status: 'accepted' },
    }));
  } catch (error) {
    error.profileSaveTargets = ['profile-nodes', 'mutation-status'];
    error.profileSaveRecovered = Boolean((await restorePendingMutation().catch(() => null))?.committed);
    throw error;
  }

  // Картка стрічки будується після тіла, а не разом з рештою індексів: правило
  // `matchingCards/$uid` вимагає, щоб анкета вже десь існувала
  // (`root.child('profileDetails').child($uid).exists()` і так далі). Поки
  // проєкція йшла перед публікацією, вона на новій анкеті мовчки відпадала за
  // правами — `syncMatchingCardIndex` помилок не кидає, — і щойно опублікована
  // картка не з'являлась ані в стрічці, ані в пошуку за частиною id.
  await withProfileSaveStage(
    'matching-card-index',
    () => syncMatchingCardIndex(cardId, acceptedProfile),
  );

  // Cleanup is best-effort: legacy overlays and child-only history rules must
  // not roll back a successfully published canonical card.
  if (Object.keys(pendingOverlayVisibility).length) {
    update(ref(database), pendingOverlayVisibility).catch(error => {
      console.warn('[profileMutations] overlay visibility cleanup unavailable', error);
    });
  }
  remove(ref(database, `${PROFILE_MUTATION_HISTORY_ROOT}/${cardId}`)).catch(error => {
    console.warn('[profileMutations] revision history cleanup unavailable', error);
  });
  releaseProfileIdentities(cardId, previousIdentityKeys.filter(key => !identityKeys.includes(key))).catch(() => {});
  return acceptedProfile;
};

export const rejectCreateProfileMutation = async ({ cardId, creatorUid, expectedRevision }) => {
  if (!cardId || !creatorUid) throw new Error('cardId and creatorUid are required');
  let conflict = 'Profile mutation not found';
  const result = await runTransaction(ref(database, getProfileMutationPath(creatorUid, cardId)), mutation => {
    if (!mutation) return undefined;
    if (mutation.status !== 'pendingReview') return undefined;
    if (Number(mutation.revision) !== Number(expectedRevision)) {
      conflict = 'REVISION_CONFLICT';
      return undefined;
    }
    return { ...mutation, status: 'private', revision: Number(mutation.revision || 0) + 1, updatedAt: Date.now() };
  }, { applyLocally: false });
  if (!result.committed) throw new Error(conflict);
  const mutation = result.snapshot.val();
  releaseProfileIdentities(cardId, mutation.identityKeys || []).catch(() => {});
  return mutation;
};

/**
 * Видалити чернетку начисто — з усіх колекцій та індексів.
 *
 * «Відхилити» (`rejectCreateProfileMutation`) повертає чернетку авторові: вона
 * лишається жити, і це правильна відповідь на «ще не готова». Але серед
 * чернеток трапляються й такі, яким жити не треба взагалі — дубль, тест,
 * випадково збережена порожнеча, — і доти єдиним способом їх прибрати було
 * не прибирати: черга адміна кнопки видалення не мала, а сама чернетка не
 * зникає ніколи.
 *
 * Чистити доводиться **всі** сліди, і це не перелік «про всяк випадок»:
 * кожен з них — місце, звідки видалена картка повертається на екран.
 *
 *   — `multiData/profileMutations/{автор}/{картка}` — сама чернетка;
 *   — `multiData/profileMutationHistory/{картка}` — журнал її ревізій;
 *   — `multiData/profileIdentityClaims/*` — заявки на унікальність. Поки вони
 *     стоять, номер видаленої чернетки лишається зайнятим, і наступна спроба
 *     завести з ним картку попереджає про дубль із карткою, якої вже немає,
 *     а нова картка заявки на свій номер не дістає;
 *   — `searchId` — чернетка лежить **тільки** там (картки стрічки в неї
 *     немає), тож без цього кроку пошук і далі знаходить те, чого немає;
 *   — шари доповнень, журнал і переліки редакторів (`purgeCardOverlays`);
 *   — публічні відгуки `comments/{картка}`: під заведеною карткою вже могли
 *     написати, і залишений відгук пережив би саму людину;
 *   — вузли анкети й `searchKey` (`removeCardAndSearchId`) — на випадок, коли
 *     чернетку вже опублікували, а видаляють картку, що з неї вийшла.
 *
 * Жоден крок не скасовує решти: права на ці вузли різні, і відмова на одному
 * не має лишати персональні дані в усіх інших. Звіт називає, що не доїхало, —
 * мовчазне «видалено» на половині видалених слідів уже коштувало б розбору.
 */
export const deleteCreateProfileMutation = async ({ cardId, creatorUid }) => {
  if (!cardId || !creatorUid) throw new Error('cardId and creatorUid are required');

  const mutationRef = ref(database, getProfileMutationPath(creatorUid, cardId));
  const snapshot = await get(mutationRef);
  const mutation = snapshot.exists() ? snapshot.val() : null;
  const data = mutation?.data || {};

  const failures = [];
  const step = async (name, run) => {
    try {
      await run();
    } catch (error) {
      failures.push({ step: name, message: error?.message || String(error) });
    }
  };

  // Заявки знімаються за тим переліком, який чернетка сама про себе зберегла;
  // якщо його немає (стара чернетка), виводимо його з даних — так само, як це
  // робить збереження.
  const identityKeys = mutation?.identityKeys?.length
    ? mutation.identityKeys
    : getSearchIdRecords(data, { contactsOnly: true }).map(getIdentityClaimKey);

  await step('identityClaims', () => releaseProfileIdentities(cardId, identityKeys));

  await step('searchId', () => Promise.all(
    getSearchIdRecords(data)
      .filter(record => keyByteLength(record.valueKey) <= 768)
      .map(record => runTransaction(
        ref(database, buildSearchIdEntryPath(record.valueKey, record.field)),
        current => removeSearchIdEntryId(current, cardId),
        { applyLocally: false },
      )),
  ));

  await step('overlays', () => purgeCardOverlays(cardId));
  await step('publicComments', () => remove(ref(database, `${PUBLIC_COMMENTS_ROOT_PATH}/${cardId}`)));
  // Вузли анкети, `searchKey` і проєкція стрічки — там же, де їх чистить
  // звичайне видалення картки. Для неопублікованої чернетки це no-op.
  await step('profileNodes', () => removeCardAndSearchId(cardId));
  // Журнал ревізій зноситься поштучно: `.write` у правилах стоїть на
  // `profileMutationHistory/$картка/$запис`, а на самій картці його немає, тож
  // один `remove` по вузлу відхиляється цілком — і мовчки, бо кроки тут
  // ізольовані.
  await step('mutationHistory', async () => {
    const historySnapshot = await get(ref(database, getProfileMutationHistoryPath(cardId)));
    if (!historySnapshot.exists()) return;
    await Promise.all(Object.keys(historySnapshot.val() || {}).map(entryId => (
      remove(ref(database, `${getProfileMutationHistoryPath(cardId)}/${entryId}`))
    )));
  });
  // Сама чернетка йде останньою: поки вона є, за нею можна відновити, що ще не
  // дочищено. Знята першою, вона забрала б із собою і перелік заявок.
  await step('mutation', () => remove(mutationRef));

  return { cardId, creatorUid, existed: Boolean(mutation), failures };
};
